  CONSTRAINT `import_job_rows_ibfk_1` FOREIGN KEY (`import_job_id`) REFERENCES `import_jobs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=944 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
